def transform(grid, tf):
    h=len(grid); w=len(grid[0])
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=0]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts); c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    border=set()
    for c in range(c0,c1+1): border.add(grid[r0][c]); border.add(grid[r1][c])
    for r in range(r0,r1+1): border.add(grid[r][c0]); border.add(grid[r][c1])
    ip=[(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if grid[r][c] not in border]
    ic=grid[ip[0][0]][ip[0][1]]
    ir1=max(p[0] for p in ip); ic1=max(p[1] for p in ip)
    t=tf(ir1-ip[0][0]+1, ic1-ip[0][1]+1)
    out=[row[:] for row in grid]
    for r in range(max(0,r0-t),min(h,r1+t+1)):
        for c in range(max(0,c0-t),min(w,c1+t+1)):
            out[r][c]=ic
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            out[r][c]=grid[r][c]
    return out
